// Python-compatible string case helpers.
//
// boltons.strutils.pluralize relies on Python's str.isupper(), str.istitle()
// and str.title() to restore the original word's casing onto the computed
// plural. These helpers reproduce that exact semantics in JavaScript.

function isCased(ch) {
  return ch.toLowerCase() !== ch.toUpperCase();
}

function isUpperChar(ch) {
  return isCased(ch) && ch === ch.toUpperCase();
}

function isLowerChar(ch) {
  return isCased(ch) && ch === ch.toLowerCase();
}

// Mirrors Python's str.isupper(): at least one cased character and every
// cased character is uppercase.
export function isUpper(s) {
  let hasCased = false;
  for (const ch of s) {
    if (!isCased(ch)) continue;
    hasCased = true;
    if (!isUpperChar(ch)) return false;
  }
  return hasCased;
}

// Mirrors Python's str.istitle(): at least one cased character; uppercase
// characters may only follow uncased characters and lowercase characters
// may only follow cased ones.
export function isTitle(s) {
  let hasCased = false;
  let prevCased = false;
  for (const ch of s) {
    if (isCased(ch)) {
      hasCased = true;
      if (prevCased && isUpperChar(ch)) return false;
      if (!prevCased && isLowerChar(ch)) return false;
      prevCased = true;
    } else {
      prevCased = false;
    }
  }
  return hasCased;
}

// Mirrors Python's str.title(): the first cased character of each group of
// cased characters is uppercased, the rest are lowercased.
export function title(s) {
  let result = '';
  let prevCased = false;
  for (const ch of s) {
    if (isCased(ch)) {
      result += prevCased ? ch.toLowerCase() : ch.toUpperCase();
      prevCased = true;
    } else {
      result += ch;
      prevCased = false;
    }
  }
  return result;
}

// Re-implementation of boltons.strutils' pluralize / singularize /
// cardinalize, matching the reference behavior character for character.
//
// Observed algorithm (black-box):
//   1. An empty word is returned unchanged.
